const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.1/companies/1234/projects/5678/calendars',
  qs: {
    'filters[calendar_id]': 'SOME_STRING_VALUE',
    'filters[name]': 'SOME_STRING_VALUE',
    'filters[is_global]': 'SOME_BOOLEAN_VALUE',
    sort: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.1/companies/1234/projects/5678/calendars?filters%5Bcalendar_id%5D=SOME_STRING_VALUE&filters%5Bname%5D=SOME_STRING_VALUE&filters%5Bis_global%5D=SOME_BOOLEAN_VALUE&sort=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

